+     */
+    public abstract void add(TDigest other);
+
+    public abstract int centroidCount();
+
+    public double getMin() {
+        return min;
+    }
+
+    public double getMax() {
+        return max;
+    }
+
+    /**
+     * Override the min and max values for testing purposes
+     */
+    void setMinMax(double min, double max) {
+        this.min = min;
+        this.max = max;
+    }
+}
