+
+    public void testBalancing() {
+        AVLGroupTree x = new AVLGroupTree();
+        for (int i = 0; i < 101; i++) {
+            x.add(new Centroid(i));
+        }
+
+        assertEquals(101, x.size());
+        assertEquals(101, x.sum());
+
+        x.checkBalance();
+        x.checkAggregates();
