+    public void testStableSort() {
+        // this needs to be long enough to force coverage of both quicksort and insertion sort
+        // (i.e. >64)
+        int n = 70;
+        int z = 10;
+        int[] order = new int[n];
+        double[] values = new double[n];
+        double[] weights = new double[n];
