+        Centroid previous = null;
+        for (Centroid centroid : digest.centroids()) {
+            if (previous != null) {
+                if (previous.mean() <= centroid.mean()) {
+                    assertTrue(Double.compare(previous.mean(), centroid.mean()) <= 0);
